const state={project:createSampleProject(),doc:{kind:'page',id:null},selectedId:null,breakpoint:'base',leftTab:'palette',rightTab:'properties',bottomTab:'problems',mode:'design',zoom:1,history:[],future:[],clipboard:null,dirty:false,issues:[],logs:[],editorView:'design',sourceFile:'',workspaceApi:false,livePreviewUrl:'',bottomExpanded:false};
function normalizeProject(){ensureResearchModel(state.project);ensureDesignProject(state.project);ensureStorybookProject(state.project);ensureCompositionModel(state.project);ensureManualLayoutProject(state.project);for(const p of state.project.pages||[])walk(p.root,n=>{ensureDesignNode(n);ensureManualLayoutNode(n);ensureCssNode(n);ensureAnimation(n)});}
