const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const now=()=>new Date().toLocaleTimeString();let recoveryTimer=0;
function log(message){state.logs.unshift({time:now(),message:String(message)});state.logs=state.logs.slice(0,250);if(state.bottomTab==='console')renderDockPanelByKey('bottom:console')}
function scheduleRecovery(){clearTimeout(recoveryTimer);recoveryTimer=setTimeout(()=>{try{localStorage.setItem('astro-ui-designer-recovery',JSON.stringify({savedAt:new Date().toISOString(),project:state.project,doc:state.doc,selectedId:state.selectedId}))}catch{}},250)}
function owner(){return state.doc.kind==='component'?state.project.components.find(x=>x.id===state.doc.id):state.project.pages.find(x=>x.id===state.doc.id)}
function root(){return owner()?.root||state.project.pages[0].root}function selected(){return findNode(root(),state.selectedId)||root()}
function checkpoint(){state.history.push(JSON.stringify(state.project));if(state.history.length>80)state.history.shift();state.future=[]}
function mutate(fn,label='Changed project'){checkpoint();fn();state.dirty=true;scheduleRecovery();log(label);renderAll()}
function activeBreakpoint(){return (state.project.settings.breakpoints||[]).find(x=>x.id===state.breakpoint)||state.project.settings.breakpoints?.[0]||{id:'base',width:1280,label:'Desktop'}}
function activeStyle(n){return {...(n.style?.base||{}),...(state.breakpoint!=='base'?n.style?.[state.breakpoint]||{}:{})}}
function domTag(n){if(n.type==='heading')return `h${Math.max(1,Math.min(6,Number(n.props?.level)||2))}`;return ({page:'main',section:'section',container:'div',row:'div',column:'div',stack:'div',grid:'div',freeform:'div',group:'div',mask:'div',shapeRect:'div',shapeEllipse:'div',svgPath:'div',rawSvg:'div',card:'div',header:'header',footer:'footer',nav:'nav',form:'form',fieldset:'fieldset',text:'p',badge:'span',list:'ul',image:'img',video:'video',icon:'span',link:'a',button:'button',label:'label',input:'input',textarea:'textarea',select:'select',checkbox:'input',radio:'input',divider:'hr',spacer:'div',slot:'div',componentInstance:'div',repeater:'div',externalComponent:'div',island:'div'}[n.type]||'div')}
function applyDomProps(el,n){const p=n.props||{};el.dataset.uiId=n.id;el.dataset.nodeId=n.id;el.classList.add('designer-node');if(n.id===state.selectedId)el.classList.add('selected');if(n.meta?.hidden)el.style.display='none';Object.assign(el.style,activeStyle(n));if(n.type==='freeform')el.classList.add('freeform-layer');if(n.meta?.className)el.classList.add(...String(n.meta.className).split(/\s+/).filter(Boolean));if(n.meta?.domId)el.id=n.meta.domId;if(n.meta?.ariaLabel)el.setAttribute('aria-label',n.meta.ariaLabel);if(n.type==='image'){el.src=p.src||'';el.alt=p.alt||''}if(n.type==='link')el.href=p.href||'#';if(n.type==='input'){el.type=p.inputType||'text';el.placeholder=p.placeholder||'';el.value=p.value||''}if(n.type==='textarea'){el.placeholder=p.placeholder||'';el.value=p.value||''}if(n.type==='button')el.type=p.buttonType||'button';if(n.type==='checkbox'){el.type='checkbox';el.checked=Boolean(p.checked)}if(n.type==='radio')el.type='radio';if(n.type==='video'&&p.src)el.src=p.src;}
function renderNode(n){const tag=domTag(n),el=document.createElement(tag);applyDomProps(el,n);if(['heading','text','badge','button','link','label','icon'].includes(n.type))el.textContent=n.props?.text||COMPONENTS[n.type]?.label||n.name;if(n.type==='rawSvg')el.innerHTML=n.props?.svg||'';if(n.type==='componentInstance'){const c=state.project.components.find(x=>x.id===n.props?.definitionId);if(c){const inner=renderNode(deepClone(c.root));inner.classList.add('component-instance-render');el.appendChild(inner)}else el.textContent='Missing component'}else if(n.type==='externalComponent')el.textContent=`External: ${n.props?.symbol||n.name}`;else if(n.type==='slot')el.textContent=n.props?.name?`Slot: ${n.props.name}`:'Default slot';else if(COMPONENTS[n.type]?.acceptsChildren)for(const c of n.children||[])el.appendChild(renderNode(c));const badge=document.createElement('span');badge.className='node-badge';badge.textContent=n.name||n.type;el.appendChild(badge);el.addEventListener('pointerdown',e=>{if(state.mode!=='design')return;e.stopPropagation();state.selectedId=n.id;renderCanvas();renderDockZones();renderStatus()});return el}
function renderCanvas(){const bp=activeBreakpoint(),art=$('#artboard');if(!art)return;art.innerHTML='';art.style.width=`${bp.width||1280}px`;art.style.transform=`scale(${state.zoom})`;art.appendChild(renderNode(root()));$('#zoom-label').textContent=`${Math.round(state.zoom*100)}%`;$('#viewport-label').textContent=`${bp.label} · ${bp.width}px`;$('#editor-stage').dataset.mode=state.mode;$('#artboard-shell').style.display=['design','preview'].includes(state.mode)?'flex':'none';$('#source-pane').style.display=['split','code'].includes(state.mode)?'grid':'none';$('#live-preview-pane').style.display=state.mode==='live'?'grid':'none';$('#component-lab-pane').style.display=state.mode==='lab'?'block':'none';if(state.mode==='split'){$('#artboard-shell').style.display='flex';$('#source-pane').style.display='grid'}}
function groupedComponents(){const m=new Map();for(const [type,spec] of Object.entries(COMPONENTS)){if(type==='page')continue;const c=spec.category||'Other';if(!m.has(c))m.set(c,[]);m.get(c).push([type,spec])}return m}
function renderLeft(){const box=$('#left-content');if(!box)return;if(state.leftTab==='palette'){box.innerHTML=`<input class="search" id="palette-search" placeholder="Filter components…">`+[...groupedComponents()].map(([cat,items])=>`<div class="group-head">${esc(cat)}</div><div class="palette-grid">${items.map(([type,s])=>`<button class="palette-item" data-add="${esc(type)}"><span class="palette-icon">${esc(s.icon||type.slice(0,2).toUpperCase())}</span><span class="palette-label">${esc(s.label)}</span></button>`).join('')}</div>`).join('');box.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>addComponent(b.dataset.add));box.querySelector('#palette-search').oninput=e=>{const q=e.target.value.toLowerCase();box.querySelectorAll('.palette-item').forEach(x=>x.style.display=x.textContent.toLowerCase().includes(q)?'flex':'none')};return}if(state.leftTab==='project'){box.innerHTML=`<div class="panel-head">Pages</div>${state.project.pages.map(p=>`<div class="project-row ${state.doc.id===p.id?'selected':''}" data-page="${p.id}"><span>◫</span><span>${esc(p.name)} <small>${esc(p.route)}</small></span></div>`).join('')}<div class="panel-head">Components</div>${state.project.components.map(c=>`<div class="project-row" data-component="${c.id}"><span>◆</span><span>${esc(c.name)}</span></div>`).join('')}`;box.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>{state.doc={kind:'page',id:x.dataset.page};state.selectedId=root().id;renderAll()});box.querySelectorAll('[data-component]').forEach(x=>x.onclick=()=>{state.doc={kind:'component',id:x.dataset.component};state.selectedId=root().id;renderAll()});return}if(state.leftTab==='components'){box.innerHTML=`<div class="left-actions"><button id="new-component">+ Component</button></div>${state.project.components.map(c=>`<div class="component-row"><span>◆</span><span>${esc(c.name)}</span></div>`).join('')||'<div class="empty">No reusable components yet.</div>'}`;box.querySelector('#new-component').onclick=()=>mutate(()=>{const r=createNode('container',{name:'ComponentRoot'}),id=`component-${Date.now().toString(36)}`;state.project.components.push({id,name:`Component ${state.project.components.length+1}`,root:r,props:[],variants:[],stories:[]})},'Created component');return}if(state.leftTab==='assets'){box.innerHTML=(state.project.assets||[]).map(a=>`<div class="asset-row"><span>▣</span><span>${esc(a.name||a.filename)}</span></div>`).join('')||'<div class="empty">Assets are embedded in the designer project or referenced by URL.</div>';return}const files=state.project.workspace?.files||[];box.innerHTML=`<div class="left-actions"><button id="rescan-workspace">Rescan</button></div>${files.map(f=>`<div class="project-row" data-source="${esc(f.filename||f.relativePath)}"><span>⌘</span><span>${esc(f.filename||f.relativePath)}</span></div>`).join('')||'<div class="empty">Open a workspace to inspect source files.</div>'}`;box.querySelector('#rescan-workspace').onclick=()=>scanWorkspace();box.querySelectorAll('[data-source]').forEach(x=>x.onclick=()=>openSourceFile(x.dataset.source,'split'))}
function addComponent(type){const parent=selected(),target=COMPONENTS[parent.type]?.acceptsChildren?parent:findParent(root(),parent.id)||root();mutate(()=>{const n=createNode(type);insertNode(root(),target.id,n);state.selectedId=n.id},`Added ${COMPONENTS[type]?.label||type}`)}
function fieldControl(n,f){const v=n.props?.[f.key]??'';if(f.kind==='select')return `<select data-prop="${esc(f.key)}">${(f.options||[]).map(o=>`<option ${String(v)===String(o)?'selected':''}>${esc(o)}</option>`).join('')}</select>`;if(f.kind==='boolean')return `<span class="check-cell"><input type="checkbox" data-prop="${esc(f.key)}" ${v?'checked':''}></span>`;if(f.kind==='textarea')return `<textarea data-prop="${esc(f.key)}">${esc(v)}</textarea>`;return `<input data-prop="${esc(f.key)}" value="${esc(v)}">`}
function renderRight(){const box=$('#right-content');if(!box)return;const n=selected(),spec=COMPONENTS[n.type]||{fields:[]};if(state.rightTab==='properties'){box.innerHTML=`<div class="inspector-title"><strong>${esc(n.name)}</strong><span>${esc(n.type)}</span></div><details class="property-section" open><summary>Content / props</summary>${(spec.fields||[]).map(f=>`<div class="property-row"><label>${esc(f.label)}</label>${fieldControl(n,f)}</div>`).join('')||'<div class="empty">No typed props.</div>'}</details><details class="property-section" open><summary>Identity</summary><div class="property-row"><label>Name</label><input data-meta-name value="${esc(n.name)}"></div><div class="property-row"><label>DOM id</label><input data-meta="domId" value="${esc(n.meta?.domId||'')}"></div><div class="property-row"><label>Class</label><input data-meta="className" value="${esc(n.meta?.className||'')}"></div><div class="property-row"><label>Source owner</label><select data-meta="sourceOwnership">${['designer','hybrid','code'].map(x=>`<option ${n.meta?.sourceOwnership===x?'selected':''}>${x}</option>`).join('')}</select></div></details>`;box.querySelectorAll('[data-prop]').forEach(x=>x.onchange=()=>mutate(()=>{n.props[x.dataset.prop]=x.type==='checkbox'?x.checked:x.value},`Changed ${x.dataset.prop}`));box.querySelector('[data-meta-name]').onchange=e=>mutate(()=>n.name=e.target.value,'Renamed node');box.querySelectorAll('[data-meta]').forEach(x=>x.onchange=()=>mutate(()=>n.meta[x.dataset.meta]=x.value,`Changed ${x.dataset.meta}`));return}if(state.rightTab==='layout'){const s=n.style?.[state.breakpoint]||{},base=activeStyle(n);box.innerHTML=`<div class="inspector-title"><strong>Layout</strong><span>${esc(state.breakpoint)}</span></div><div class="property-section"><div class="property-row"><label>Display</label><select data-style="display">${['','block','flex','grid','inline-flex','none'].map(v=>`<option value="${v}" ${base.display===v?'selected':''}>${v||'default'}</option>`).join('')}</select></div>${['width','height','minWidth','maxWidth','gap','padding','margin','background','color','border','borderRadius','fontSize','fontWeight','textAlign','justifyContent','alignItems','gridTemplateColumns','position','left','top','overflow'].map(k=>`<div class="property-row"><label>${k}</label><input data-style="${k}" value="${esc(s[k]??base[k]??'')}"></div>`).join('')}<div class="property-row"><label>Width mode</label><select data-size="x">${SIZING_MODES.map(v=>`<option>${v}</option>`).join('')}</select></div><div class="property-row"><label>Position</label><select data-position>${POSITION_MODES.map(v=>`<option ${base.position===v?'selected':''}>${v}</option>`).join('')}</select></div></div>`;box.querySelectorAll('[data-style]').forEach(x=>x.onchange=()=>mutate(()=>{n.style[state.breakpoint]??={};if(x.value)n.style[state.breakpoint][x.dataset.style]=x.value;else delete n.style[state.breakpoint][x.dataset.style]},`Style ${x.dataset.style}`));box.querySelector('[data-size]').onchange=e=>mutate(()=>applySizingMode(n,e.target.dataset.size,e.target.value),'Changed sizing mode');box.querySelector('[data-position]').onchange=e=>mutate(()=>setPositionMode(n,e.target.value),'Changed position mode');return}if(state.rightTab==='code'){const info=inspectNode(n);box.innerHTML=`<div class="inspector-title"><strong>Generated code</strong></div><pre class="code-preview">${esc(info.html)}\n\n${esc(info.css)}</pre>`;return}if(state.rightTab==='effects'){const d=ensureDesignNode(n);box.innerHTML=`<div class="inspector-title"><strong>Effects</strong></div><div class="hint">Penpot-inspired clean-room effects: ${d.effects.fills.length} fills, ${d.effects.strokes.length} strokes, ${d.effects.shadows.length} shadows.</div><div class="property-row"><label>Blend</label><input value="${esc(d.effects.blendMode||'normal')}" disabled></div>`;return}if(state.rightTab==='composition'){const sum=compositionSummary(state.project);box.innerHTML=`<div class="inspector-title"><strong>Composition</strong></div><div class="hint">${sum.mixins} mixins · ${sum.globalVariants} global variants · ${sum.queries} queries · ${sum.templates} templates.</div>`;return}if(state.rightTab==='story'){const sum=storybookSummary(state.project);box.innerHTML=`<div class="inspector-title"><strong>Component Lab</strong></div><div class="hint">${sum.components} components · ${sum.stories} stories · ${sum.baselines} visual baselines.</div>`;return}box.innerHTML=`<div class="inspector-title"><strong>${esc(state.rightTab)}</strong></div><div class="hint">This inspector is backed by the project model and plugin API. Use the workbench below for advanced editing.</div>`}
function treeRows(n,depth=0){return `<div class="tree-row ${n.id===state.selectedId?'selected':''}" data-tree="${n.id}" style="padding-left:${depth*14+6}px"><span>▸</span><span class="tree-kind">${esc(n.type)}</span><span class="tree-name">${esc(n.name)}</span></div>${(n.children||[]).map(c=>treeRows(c,depth+1)).join('')}`}
function downloadInterchangeArtifact(name,text,mime='application/octet-stream'){const blob=new Blob([text],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importDrawioFile(file){const text=await file.text();if(!isDrawioText(text)&&!String(file.name||'').toLowerCase().endsWith('.drawio'))throw new Error('The selected file is not a Draw.io / diagrams.net document.');const project=await importDrawioText(text,{projectName:String(file.name||'drawio-import').replace(/\.(drawio|xml)$/i,'')});loadProjectObject(project);state.dirty=true;log(`Imported Draw.io: ${file.name} · ${project.pages.length} page(s) · ${project.design?.interchange?.drawio?.edges?.length||0} connector(s)`);renderAll();return project}
function openDrawioImportPicker(){const input=document.createElement('input');input.type='file';input.accept='.drawio,.xml,.svg,application/xml,text/xml,image/svg+xml';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{await importDrawioFile(file)}catch(e){alert(`Draw.io import failed: ${e.message}`);log(`Draw.io import failed: ${e.message}`)}};input.click()}
function exportDrawioFile(){try{const text=exportDrawio(state.project);downloadInterchangeArtifact(`${state.project.name||'astro-ui-project'}.drawio`,text,DRAWIO_MIME);log(`Exported Draw.io · ${state.project.pages.length} page(s)`);return text}catch(e){alert(`Draw.io export failed: ${e.message}`);log(`Draw.io export failed: ${e.message}`);return''}}
function renderInterchangePanel(box){const adapters=listPlatformAdapters(),drawioMeta=state.project.design?.interchange?.drawio;box.innerHTML=`<div class="workbench-grid"><div class="workbench-card"><strong>Draw.io / diagrams.net</strong><p>Import editable .drawio/.xml diagrams into freeform designer nodes, preserving geometry, labels, styling and connector metadata. Export the current project as standard editable mxGraph XML.</p><div class="inspector-toolbar"><button id="drawio-import" class="primary">Import .drawio</button><button id="drawio-export">Export .drawio</button></div><div class="meta">${drawioMeta?`Imported pages: ${drawioMeta.pages?.length||0} · preserved connectors: ${drawioMeta.edges?.length||0}`:'No Draw.io metadata in this project yet.'}</div></div><div class="workbench-card"><strong>Interchange adapters</strong>${adapters.map(a=>`<div class="source-row"><span>◇</span><span>${esc(a.label)}<br><small>${esc(a.direction||'both')}${a.extensions?` · ${esc(a.extensions.join(', '))}`:''}</small></span><span>${a.id==='drawio'?'active':''}</span></div>`).join('')}</div></div>`;box.querySelector('#drawio-import').onclick=openDrawioImportPicker;box.querySelector('#drawio-export').onclick=exportDrawioFile}
function renderBottom(){const box=$('#bottom-content');if(!box)return;if(!state.bottomExpanded){box.innerHTML='';return}if(state.bottomTab==='problems'){state.issues=validateProject(state.project);box.innerHTML=state.issues.map(i=>`<div class="problem-row"><span class="sev-${i.severity}">${esc(i.severity)}</span><span>${esc(i.code)}</span><span>${esc(i.message)}</span></div>`).join('')||'<div class="empty">No problems.</div>';$('#problem-count').textContent=state.issues.length||'';return}if(state.bottomTab==='objects'){box.innerHTML=treeRows(root());box.querySelectorAll('[data-tree]').forEach(x=>x.onclick=()=>{state.selectedId=x.dataset.tree;renderCanvas();renderDockZones();renderStatus()});return}if(state.bottomTab==='console'){box.innerHTML=state.logs.map(x=>`<div class="log-row"><span class="log-time">${esc(x.time)}</span>${esc(x.message)}</div>`).join('');return}if(state.bottomTab==='interchange'){renderInterchangePanel(box);return}if(state.bottomTab==='integrations'){const plugins=getDesignerPlugins(),contrib=getDesignerContributions();box.innerHTML=`<div class="workbench-grid"><div class="workbench-card"><strong>Plugins</strong>${plugins.map(p=>`<div>${esc(p.name||p.id)} <small>${esc(p.version||'')}</small></div>`).join('')||'<div>None</div>'}</div>${Object.entries(contrib).map(([kind,items])=>`<div class="workbench-card"><strong>${esc(kind)}</strong>${(items||[]).map(x=>`<button class="provider-btn" data-kind="${esc(kind)}" data-id="${esc(x.id)}">${esc(x.label||x.name||x.id)}</button>`).join('')||'<div>None</div>'}</div>`).join('')}</div>`;box.querySelectorAll('.provider-btn').forEach(b=>b.onclick=async()=>{const item=(contrib[b.dataset.kind]||[]).find(x=>x.id===b.dataset.id);try{const r=await item?.run?.({project:state.project,node:selected(),selection:[selected()]});log(`${item?.label||item?.id}: ${JSON.stringify(r)}`);renderDockPanelByKey('bottom:integrations')}catch(e){log(`Provider error: ${e.message}`)}});return}if(state.bottomTab==='roundtrip'){box.innerHTML=`<div class="workbench-grid"><div class="workbench-card"><strong>Round-trip Studio</strong><p>Syntax-aware source ↔ design synchronization, history, conversion and backend adapters.</p><button id="open-roundtrip-studio" class="primary">Open Round-trip Studio</button></div><div class="workbench-card"><strong>Workspace</strong><div>${esc(state.project.workspace?.rootPath||'No workspace open')}</div><div>${state.project.workspace?.files?.length||0} indexed files</div></div></div>`;box.querySelector('#open-roundtrip-studio').onclick=()=>window.AstroUIDesignerRoundTrip?.openStudio?.();return}if(state.bottomTab==='animation'){const a=ensureAnimation(selected());box.innerHTML=`<div class="workbench-grid"><div class="workbench-card"><strong>Animation</strong><div>${a.tracks.length} tracks · ${a.duration}ms · ${esc(a.engine)}</div>${Object.entries(ANIMATION_PRESETS).map(([id,p])=>`<button data-preset="${id}">${esc(p.label)}</button>`).join('')}</div></div>`;box.querySelectorAll('[data-preset]').forEach(x=>x.onclick=()=>mutate(()=>applyAnimationPreset(selected(),x.dataset.preset),'Applied animation preset'));return}if(state.bottomTab==='audit'){const a=summarizeResearchFeatures(state.project),p=prototypeSummary(state.project);box.innerHTML=`<div class="workbench-grid"><div class="workbench-card"><strong>Research feature audit</strong><pre>${esc(JSON.stringify(a,null,2))}</pre></div><div class="workbench-card"><strong>Prototype</strong><pre>${esc(JSON.stringify(p,null,2))}</pre></div></div>`;return}box.innerHTML=`<div class="workbench-card"><strong>${esc(state.bottomTab)}</strong><p>Workbench data is retained in the project model. This source reconstruction keeps the current model, plugin, export and round-trip APIs directly editable.</p></div>`}
function documentTabItems(){return [...state.project.pages.map(p=>({key:`page:${p.id}`,kind:'page',id:p.id,name:p.name})),...state.project.components.map(c=>({key:`component:${c.id}`,kind:'component',id:c.id,name:c.name}))]}
