function bindStaticEvents(){
  // Dock tab click/drag handlers are installed by initDocking().
  $('#bottom-toggle-btn').onclick=()=>{state.bottomExpanded=!state.bottomExpanded;$('#app').classList.toggle('bottom-minimized',!state.bottomExpanded);renderDockZone('bottom');$('#bottom-toggle-btn').textContent=state.bottomExpanded?'⌄':'⌃'};
  $('#breakpoint-select').innerHTML=(state.project.settings.breakpoints||[]).map(b=>`<option value="${b.id}">${esc(b.label)} · ${b.width}</option>`).join('');$('#breakpoint-select').onchange=e=>{state.breakpoint=e.target.value;renderCanvas();renderDockZones()};
  $('#design-mode-btn').onclick=()=>setMode('design');$('#split-mode-btn').onclick=()=>setMode('split');$('#code-mode-btn').onclick=()=>setMode('code');$('#preview-mode-btn').onclick=()=>setMode('preview');$('#component-lab-mode-btn').onclick=()=>setMode('lab');
  $('#zoom-out-btn').onclick=()=>{state.zoom=Math.max(.25,state.zoom-.1);renderCanvas()};$('#zoom-in-btn').onclick=()=>{state.zoom=Math.min(2,state.zoom+.1);renderCanvas()};$('#fit-btn').onclick=()=>{const w=$('#artboard-shell').clientWidth-60;state.zoom=Math.min(1,Math.max(.25,w/activeBreakpoint().width));renderCanvas()};
  $('#new-btn').onclick=()=>loadProjectObject(createSampleProject());$('#save-btn').onclick=saveProject;$('#open-btn').onclick=()=>$('#file-open').click();$('#file-open').onchange=async e=>{const f=e.target.files?.[0];if(f)loadProjectObject(JSON.parse(await f.text()));e.target.value=''};
  $('#undo-btn').onclick=()=>{if(!state.history.length)return;state.future.push(JSON.stringify(state.project));state.project=JSON.parse(state.history.pop());normalizeProject();renderAll()};$('#redo-btn').onclick=()=>{if(!state.future.length)return;state.history.push(JSON.stringify(state.project));state.project=JSON.parse(state.future.pop());normalizeProject();renderAll()};
  $('#copy-btn').onclick=()=>state.clipboard=deepClone(selected());$('#cut-btn').onclick=()=>{if(selected().id===root().id)return;state.clipboard=deepClone(selected());mutate(()=>{removeNode(root(),selected().id);state.selectedId=root().id},'Cut node')};$('#paste-btn').onclick=()=>{if(!state.clipboard)return;const p=selected();if(!COMPONENTS[p.type]?.acceptsChildren)return;mutate(()=>{const n=deepClone(state.clipboard);walk(n,x=>x.id=`${x.type}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`);p.children.push(n);state.selectedId=n.id},'Pasted node')};$('#duplicate-btn').onclick=()=>mutate(()=>{const n=duplicateNode(root(),selected().id);if(n)state.selectedId=n.id},'Duplicated node');$('#delete-btn').onclick=()=>{if(selected().id!==root().id)mutate(()=>{removeNode(root(),selected().id);state.selectedId=root().id},'Deleted node')};
  $('#export-btn').onclick=()=>downloadZip(generateAstroProject(state.project),`${state.project.name||'astro-ui-project'}.zip`);$('#workspace-btn').onclick=async()=>{const p=prompt('Workspace path',state.project.workspace?.rootPath||'');if(p)try{await openWorkspacePath(p)}catch(e){alert(e.message)}};$('#live-preview-btn').onclick=async()=>{try{if(state.livePreviewUrl){await stopPreview();state.livePreviewUrl='';setMode('design')}else{const r=await startPreview();state.livePreviewUrl=r.url;$('#live-preview-frame').src=r.url;setMode('live')}}catch(e){alert(e.message)}};
  $('#dock-layout-btn').onclick=e=>showDockLayoutMenu(e);$('#roundtrip-btn').onclick=()=>window.AstroUIDesignerRoundTrip?.openStudio?.()||openBottomTab('roundtrip');$('#source-file-select').onchange=e=>openSourceFile(e.target.value,state.mode);$('#source-reload-btn').onclick=()=>state.sourceFile&&openSourceFile(state.sourceFile,state.mode);$('#source-apply-btn').onclick=async()=>{if(!state.sourceFile)return;await writeWorkspaceFile(state.sourceFile,$('#source-editor').value);addSourceSnapshot(state.project,state.sourceFile,$('#source-editor').value);log(`Saved ${state.sourceFile}`)};$('#source-sync-btn').onclick=async()=>{if(!state.sourceFile)return;const n=selected(),patched=patchAstroNodeByUiId($('#source-editor').value,n.id,{text:n.props?.text,attributes:{class:n.meta?.className||null,id:n.meta?.domId||null}});if(patched.changed)$('#source-editor').value=patched.source;else alert('No data-ui-id mapping found for selection.')};
  document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveProject()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$('#undo-btn').click()}if(e.key==='Delete'&&document.activeElement?.tagName!=='INPUT'&&document.activeElement?.tagName!=='TEXTAREA')$('#delete-btn').click()});
}
